public final class Zones {
 public record Config(int schema,Map<String,MobSpec> mobs,Map<String,LootSpec> loot,Map<String,ZoneSpec> zones){
  public Config{if(schema!=1&&schema!=2&&schema!=3&&schema!=4&&schema!=5&&schema!=6&&schema!=7)throw new IllegalArgumentException("Versión de configuración desconocida");mobs=Map.copyOf(mobs);loot=Map.copyOf(loot);zones=Map.copyOf(zones);for(var table:loot.values())if(table.independent()){for(var mob:mobs.values())if(mob.boss()&&mob.loot().equals(table.id()))throw new IllegalArgumentException("Porcentajes independientes solo para mobs normales");for(var zone:zones.values())if(zone.completionLoot().equals(table.id()))throw new IllegalArgumentException("El premio de zona requiere una tabla de selección");}if(mobs.size()>256||loot.size()>256||zones.size()>128)throw new IllegalArgumentException("Demasiadas definiciones");for(var e:mobs.entrySet()){if(!e.getKey().equals(e.getValue().id()))throw new IllegalArgumentException("ID de mob distinto de su clave");if(!e.getValue().loot().isEmpty()&&!loot.containsKey(e.getValue().loot()))throw new IllegalArgumentException("Loot de mob inexistente");}for(var e:loot.entrySet())if(!e.getKey().equals(e.getValue().id()))throw new IllegalArgumentException("ID de loot distinto de su clave");final var mobDefinitions=mobs;for(var e:zones.entrySet()){var z=e.getValue();if(!e.getKey().equals(z.id())||!mobs.keySet().containsAll(z.referencedMobs())||z.stages()==null&&!z.boss().isEmpty()&&!mobs.get(z.boss()).boss()||z.stages()!=null&&z.stages().stream().anyMatch(s->s.kind()==StageKind.BOSS&&!mobDefinitions.get(s.team().getFirst()).boss())||(!z.completionLoot().isEmpty()&&!loot.containsKey(z.completionLoot()))||z.enabled()&&!z.autoSpawn()&&z.points().isEmpty())throw new IllegalArgumentException("Referencias o puntos de zona inválidos");}}
 }
 MinecraftServer server;Config config;private Path root,configFile;EncounterLedger ledger;RewardJournal rewards;private int ticks;
 private record Death(Mob mob,ServerPlayer killer){}
 private final Map<UUID,net.minecraft.server.level.ServerBossEvent> bars=new HashMap<>();
 private final List<Death> deaths=new ArrayList<>();private final Map<UUID,Integer> missing=new HashMap<>();private final Map<String,Long> retry=new HashMap<>();
 final MobsAdmin admin;final ZoneHolograms holograms=new ZoneHolograms();final ZonePreview previews=new ZonePreview();
 public Zones(){admin=new MobsAdmin(this);MobsNetwork.admin=admin;
  NeoForge.EVENT_BUS.addListener((ServerStartedEvent e)->start(e.getServer()));
  NeoForge.EVENT_BUS.addListener((ServerStoppedEvent e)->{admin.clear();PersonalRewards.clear();holograms.clear();previews.clear();Tuning.stop();server=null;config=null;ledger=null;rewards=null;references=null;bars.values().forEach(net.minecraft.server.level.ServerBossEvent::removeAllPlayers);bars.clear();deaths.clear();missing.clear();retry.clear();try{com.ianblk.zianmobs.storage.StorageFiles.closeAll();}catch(Exception failure){ZianMobs.LOGGER.error("Cannot close reward storage",failure);}});
  NeoForge.EVENT_BUS.addListener(this::tick);
  NeoForge.EVENT_BUS.addListener(EventPriority.LOWEST,(LivingDeathEvent e)->{if(ledger!=null && e.getEntity() instanceof Mob mob && mob.getPersistentData().contains("ZianMobsRun"))deaths.add(new Death(mob,e.getSource().getEntity() instanceof ServerPlayer player?player:null));});
  NeoForge.EVENT_BUS.addListener(EventPriority.LOWEST,(LivingDropsEvent e)->{if(ledger!=null && owned(e.getEntity()))e.getDrops().clear();});
  NeoForge.EVENT_BUS.addListener((RegisterCommandsEvent e)->commands(e.getDispatcher()));
  NeoForge.EVENT_BUS.addListener((net.neoforged.neoforge.event.entity.EntityJoinLevelEvent e)->{if(!e.getLevel().isClientSide&&e.getEntity().getPersistentData().getBoolean(ZoneHolograms.TAG)&&!holograms.owns(e.getEntity().getUUID())){e.setCanceled(true);return;}if(!e.getLevel().isClientSide&&ledger!=null&&e.getEntity() instanceof Mob mob&&mob.getPersistentData().contains("ZianMobsRun")&&!allowedEntity(mob))e.setCanceled(true);});
 }
 private void start(MinecraftServer value){try{server=value;root=server.getWorldPath(LevelResource.ROOT).resolve("data/zianmobs");configFile=root.resolve("config.json");Tuning.start(root);Config initial=defaults();config=AtomicJson.read(configFile,Config.class,initial);var originalConfig=config;if(config.schema()<7&&!com.ianblk.zianmobs.storage.StorageFiles.exists(root.resolve("config-before-consolidation-v7.json")))AtomicJson.write(root.resolve("config-before-consolidation-v7.json"),config);if(config.schema()<6&&!com.ianblk.zianmobs.storage.StorageFiles.exists(root.resolve("config-before-ordered-stages-v6.json")))AtomicJson.write(root.resolve("config-before-ordered-stages-v6.json"),config);if(config.schema()<5){var added=new LinkedHashMap<>(config.mobs());initial.mobs().forEach((id,m)->{if(id.startsWith("npc_"))added.putIfAbsent(id,m);});config=new Config(config.schema(),added,config.loot(),config.zones());}if(config.schema()==1){var upgraded=new LinkedHashMap<>(config.mobs());initial.mobs().forEach(upgraded::putIfAbsent);config=new Config(7,upgraded,config.loot(),config.zones());}var before=config;var retirement=ContentRetirement.migrate(before,ContentRetirement::itemTag);config=retirement.config();if(!before.equals(config)){var backup=root.resolve("config-before-beta4.json");if(!com.ianblk.zianmobs.storage.StorageFiles.exists(backup))AtomicJson.write(backup,originalConfig);ZianMobs.LOGGER.info("Retired content migrated; disabled zones: {}",retirement.affectedZones());}config=new Config(7,config.mobs(),config.loot(),config.zones());validateRegistry(config);var pendingPath=root.resolve("retired-zones-beta4-pending.json");var pending=new HashSet<>(List.of(AtomicJson.read(pendingPath,String[].class,new String[0])));pending.addAll(retirement.affectedZones());AtomicJson.write(pendingPath,pending);AtomicJson.write(configFile,config);ledger=new EncounterLedger(root.resolve("encounters.json"));rewards=RewardJournal.open(root.resolve("claims.json"));for(String id:pending)if(config.zones().containsKey(id))cancel(config.zones().get(id));AtomicJson.write(pendingPath,List.of());for(var world:server.getAllLevels())for(var entity:world.getAllEntities())if(entity instanceof Mob mob&&mob.getPersistentData().contains("ZianMobsRun")&&!allowedEntity(mob))mob.discard();ZianMobs.LOGGER.info("Zian Mobs zones loaded: {}",config.zones().size());}catch(Exception error){config=null;ledger=null;rewards=null;ZianMobs.LOGGER.error("Zian Mobs zones disabled; existing files preserved",error);}}
 private static Config defaults(){Map<String,MobSpec> mobs=new LinkedHashMap<>();for(String id:List.of("cursed_one_forest","cursed_one_ice","cursed_one_crystal","oni_brute"))mobs.put(id,new MobSpec(id,id,"zianmobs:"+id,id.equals("oni_brute")?50:25,id.equals("oni_brute")?10:3,0,0,.7,List.of(),Map.of(),"",id.equals("oni_brute")));mobs.put("snowbone",new MobSpec("snowbone","Snowbone · Vigía de la Escarcha","zianmobs:snowbone",20,3,0,0,.2,List.of(),Map.of(),"",false));for(var skin:NpcProfiles.SKINS){String id="npc_"+skin.id();mobs.put(id,new MobSpec(id,skin.name(),"zianmobs:combat_npc",40,6,0,0,0,List.of(),Map.of("mainhand","{id:\"minecraft:iron_sword\",count:1}"),"",false));}return new Config(7,mobs,Map.of(),Map.of());}
 void ready(){if(config==null||ledger==null||rewards==null)throw new IllegalStateException("Zonas no disponibles; revisa el registro del servidor");}
 private static String dimension(ServerPlayer p){return p.serverLevel().dimension().location().toString();}
 private ServerLevel level(String name){return server.getLevel(ResourceKey.create(Registries.DIMENSION,ResourceLocation.parse(name)));}
 private void validateRegistry(Config next){for(var spec:next.mobs().values()){var id=ResourceLocation.parse(spec.entity());if(!BuiltInRegistries.ENTITY_TYPE.containsKey(id))throw new IllegalArgumentException("Entidad desconocida: "+id);if(!(BuiltInRegistries.ENTITY_TYPE.get(id).create(server.overworld()) instanceof Mob))throw new IllegalArgumentException("Selecciona una entidad de tipo mob");for(var equipment:spec.equipment().values())if(item(equipment).isEmpty())throw new IllegalArgumentException("Equipo desconocido");for(var effect:spec.effects())if(!BuiltInRegistries.MOB_EFFECT.containsKey(ResourceLocation.parse(effect.id())))throw new IllegalArgumentException("Efecto desconocido");}for(var zone:next.zones().values())if(level(zone.dimension())==null)throw new IllegalArgumentException("Dimensión desconocida: "+zone.dimension());for(var zone:next.zones().values())if(zone.enabled()&&!zone.autoSpawn())for(var point:zone.points())if(!zone.contains(zone.dimension(),point.x(),point.y(),point.z()))throw new IllegalArgumentException("Punto fuera de la zona");for(var spec:next.loot().values()){for(var entry:spec.entries()){var stack=item(entry.item());if(stack.isEmpty()||entry.max()>stack.getMaxStackSize())throw new IllegalArgumentException("Objeto o cantidad inválidos");}}}
 void validateImport(Config next){validateRegistry(next);}
 void save(Config next)throws Exception{validateRegistry(next);AtomicJson.write(configFile,next);config=next;}
 private boolean allowedEntity(Mob mob){var run=ledger.get(mob.getPersistentData().getString("ZianMobsZone"));return run!=null&&run.phase()==Phase.ACTIVE&&run.uuid().toString().equals(mob.getPersistentData().getString("ZianMobsRun"))&&run.spawns().stream().anyMatch(s->s.uuid().equals(mob.getUUID())&&!s.defeated());}
 private boolean owned(LivingEntity entity){var tag=entity.getPersistentData();var run=ledger.get(tag.getString("ZianMobsZone"));return run!=null && run.uuid().toString().equals(tag.getString("ZianMobsRun")) && run.spawns().stream().anyMatch(s->s.uuid().equals(entity.getUUID()));}
 private void tick(ServerTickEvent.Post event){if(event.getServer()!=server||ledger==null)return;for(var death:List.copyOf(deaths))if(!death.mob().isAlive())died(death);deaths.clear();if(++ticks%10==0)previews.tick(server);if(ticks%20!=0)return;for(var player:server.getPlayerList().getPlayers()){for(var stack:player.getInventory().items)Tuning.update(stack);for(var stack:player.getInventory().armor)Tuning.update(stack);for(var stack:player.getInventory().offhand)Tuning.update(stack);player.inventoryMenu.broadcastChanges();}long now=System.currentTimeMillis();holograms.update(server,config,ledger,now,Tuning.current.settings().zones());bars.entrySet().removeIf(e->{for(var world:server.getAllLevels())if(world.getEntity(e.getKey()) instanceof LivingEntity living&&living.isAlive())return false;e.getValue().removeAllPlayers();return true;});bars.values().forEach(net.minecraft.server.level.ServerBossEvent::removeAllPlayers);for(var zone:config.zones().values()){if(!zone.enabled()||!Tuning.current.settings().zones())continue;try{var players=server.getPlayerList().getPlayers().stream().filter(p->!p.isCreative()&&!p.isSpectator()&&p.isAlive()&&zone.contains(dimension(p),p.getX(),p.getY(),p.getZ())).map(ServerPlayer::getUUID).collect(java.util.stream.Collectors.toCollection(LinkedHashSet::new));if(players.isEmpty())continue;var run=ledger.get(zone.id());if(run==null||(run.phase()==Phase.COMPLETE||run.phase()==Phase.CANCELLED)&&now>=run.readyAt()){if(now>=retry.getOrDefault(zone.id(),0L))begin(zone,players,1,UUID.randomUUID());continue;}if(run.phase()==Phase.WAITING&&now>=run.readyAt()&&now>=retry.getOrDefault(zone.id(),0L)){begin(zone,players,run.wave()+1,run.uuid());continue;}if(run.phase()!=Phase.ACTIVE)continue;if(run.baseMobs()>0&&players.size()>run.scaledPlayers()&&now>=retry.getOrDefault(zone.id(),0L))run=grow(zone,run,players);var participants=new LinkedHashSet<>(run.players());participants.addAll(players);if(!participants.equals(run.players())){run=new Run(run.uuid(),run.zone(),run.wave(),run.phase(),run.readyAt(),run.spawns(),participants,run.baseMobs(),run.scaledPlayers());ledger.put(run);}var world=level(zone.dimension());for(var slot:run.spawns())if(!slot.defeated()){var entity=world.getEntity(slot.uuid());if(entity==null){var pos=BlockPos.containing(slot.point().x(),slot.point().y(),slot.point().z());if(world.hasChunkAt(pos)&&missing.merge(slot.uuid(),1,Integer::sum)>=5)ledger.put(new Run(run.uuid(),run.zone(),run.wave(),Phase.REVIEW,0,run.spawns(),run.players(),run.baseMobs(),run.scaledPlayers()));}else{missing.remove(slot.uuid());if(entity instanceof LivingEntity living&&Tuning.current.settings().bossbars()&&config.mobs().get(slot.template()).boss()){var bar=bars.computeIfAbsent(entity.getUUID(),id->new net.minecraft.server.level.ServerBossEvent(Component.literal(config.mobs().get(slot.template()).name()),net.minecraft.world.BossEvent.BossBarColor.RED,net.minecraft.world.BossEvent.BossBarOverlay.PROGRESS));bar.setProgress(Math.max(0,Math.min(1,living.getHealth()/living.getMaxHealth())));for(UUID id:players){var player=server.getPlayerList().getPlayer(id);if(player!=null)bar.addPlayer(player);}}if(Tuning.current.settings().leash()&&!zone.contains(zone.dimension(),entity.getX(),entity.getY(),entity.getZ()))entity.teleportTo(slot.point().x(),slot.point().y(),slot.point().z());}}}catch(Exception error){retry.put(zone.id(),now+10000);ZianMobs.LOGGER.error("Zone {} needs review",zone.id(),error);}}}
 private record PreparedWave(List<Mob> mobs,List<Spawn> slots){}
 private PreparedWave prepare(ZoneSpec zone,int stage,UUID runId,int count,boolean pool,List<Spawn> current){
  var world=level(zone.dimension());var prepared=new ArrayList<Mob>();var slots=new ArrayList<Spawn>();var team=zone.teamForStage(stage);var occupied=new ArrayList<net.minecraft.world.phys.AABB>();for(var slot:current)if(!slot.defeated()){var entity=world.getEntity(slot.uuid());if(entity!=null)occupied.add(entity.getBoundingBox());}
  for(int i=0;i<count;i++){String name=team.get(pool?world.random.nextInt(team.size()):i);var spec=config.mobs().get(name);var entity=BuiltInRegistries.ENTITY_TYPE.get(ResourceLocation.parse(spec.entity())).create(world);if(!(entity instanceof Mob chosen))throw new IllegalArgumentException("La entidad no es un mob");Point chosenPoint=SafeZoneSpawn.find(world,zone,chosen,occupied);if(chosenPoint==null)throw new IllegalStateException("No hay suelo seguro o puntos suficientes para toda la oleada");occupied.add(chosen.getBoundingBox());
  if(chosen instanceof CombatNpc npc)npc.configure(spec.id());chosen.setPersistenceRequired();chosen.setCustomName(Component.literal(spec.name()));for(var attribute:Map.of(Attributes.MAX_HEALTH,spec.health(),Attributes.ATTACK_DAMAGE,spec.damage(),Attributes.ARMOR,spec.armor(),Attributes.ARMOR_TOUGHNESS,spec.toughness(),Attributes.KNOCKBACK_RESISTANCE,spec.knockback()).entrySet()){var instance=chosen.getAttribute(attribute.getKey());if(instance!=null)instance.setBaseValue(attribute.getValue());}chosen.setHealth((float)spec.health());for(var equipment:spec.equipment().entrySet())chosen.setItemSlot(EquipmentSlot.byName(equipment.getKey()),item(equipment.getValue()));for(var effect:spec.effects()){var holder=BuiltInRegistries.MOB_EFFECT.getHolder(ResourceLocation.parse(effect.id()));if(holder.isEmpty())throw new IllegalArgumentException("Efecto desconocido");chosen.addEffect(new net.minecraft.world.effect.MobEffectInstance(holder.get(),effect.seconds()*20,effect.amplifier()));}chosen.getPersistentData().putString("ZianMobsRun",runId.toString());chosen.getPersistentData().putString("ZianMobsZone",zone.id());prepared.add(chosen);slots.add(new Spawn(chosen.getUUID(),name,chosenPoint,false));}
  return new PreparedWave(prepared,slots);
 }
 private void publish(ZoneSpec zone,Run run,PreparedWave prepared)throws Exception{ledger.put(run);try{for(var mob:prepared.mobs())if(!level(zone.dimension()).addFreshEntity(mob))throw new IllegalStateException("Aparición rechazada");}catch(Exception error){ledger.put(new Run(run.uuid(),zone.id(),run.wave(),Phase.REVIEW,0,run.spawns(),run.players(),run.baseMobs(),run.scaledPlayers()));throw error;}}
 private void begin(ZoneSpec zone,Set<UUID> players,int stage,UUID runId)throws Exception{
  boolean pool=zone.stages()!=null&&zone.stages().get(stage-1).population()==Population.POOL;int base=pool?1+level(zone.dimension()).random.nextInt(3):0,count=pool?ZonePopulation.target(base,Math.max(1,players.size())):zone.teamForStage(stage).size();if(pool&&!zone.autoSpawn())count=Math.min(count,zone.points().size());var prepared=prepare(zone,stage,runId,count,pool,List.of());publish(zone,new Run(runId,zone.id(),stage,Phase.ACTIVE,0,prepared.slots(),players,base,pool?Math.max(1,players.size()):0),prepared);announce(zone,zone.stageLabel(stage)+" · ¡Comienza el combate!");
 }
 private Run grow(ZoneSpec zone,Run run,Set<UUID> players)throws Exception{int target=ZonePopulation.target(run.baseMobs(),Math.max(1,players.size()));if(!zone.autoSpawn())target=Math.min(target,zone.points().size());int extra=target-run.spawns().size();if(extra<=0)return run;var prepared=prepare(zone,run.wave(),run.uuid(),extra,true,run.spawns());var slots=new ArrayList<>(run.spawns());slots.addAll(prepared.slots());var participants=new LinkedHashSet<>(run.players());participants.addAll(players);var next=new Run(run.uuid(),zone.id(),run.wave(),Phase.ACTIVE,0,slots,participants,run.baseMobs(),players.size());publish(zone,next,prepared);return next;}
 private void died(Death death){var mob=death.mob();if(!owned(mob))return;String zoneId=mob.getPersistentData().getString("ZianMobsZone");var zone=config.zones().get(zoneId);var run=ledger.get(zoneId);if(zone==null||run.phase()!=Phase.ACTIVE)return;var slot=run.spawns().stream().filter(s->s.uuid().equals(mob.getUUID())).findFirst().orElseThrow();if(slot.defeated())return;try{var spec=config.mobs().get(slot.template());if(death.killer()!=null&&!spec.loot().isEmpty())grant(death.killer().getUUID(),"mob."+mob.getUUID(),spec.loot(),mob.blockPosition(),mob.level() instanceof ServerLevel l?l:server.overworld());boolean complete=run.wave()>=zone.totalStages()&&run.spawns().stream().allMatch(s->s.defeated()||s.uuid().equals(mob.getUUID()));if(complete&&!zone.completionLoot().isEmpty())for(UUID id:run.players()){var player=server.getPlayerList().getPlayer(id);if(player!=null&&player.isAlive()&&!player.isCreative()&&!player.isSpectator()&&zone.contains(dimension(player),player.getX(),player.getY(),player.getZ()))grant(id,"zone."+run.uuid(),zone.completionLoot(),mob.blockPosition(),level(zone.dimension()));}if(ledger.defeated(zoneId,run.uuid(),mob.getUUID(),zone.totalStages(),zone.pauseSeconds(),zone.respawnSeconds(),System.currentTimeMillis())){var next=ledger.get(zoneId);if(next.phase()==Phase.WAITING)announce(zone,(zone.stageLabel(run.wave())+" superada · "+zone.stageLabel(run.wave()+1))+" en "+ZoneStatus.countdown((long)zone.pauseSeconds()*1000));else if(next.phase()==Phase.COMPLETE)announce(zone,"¡Encuentro completado! "+"Todas las etapas superadas"+" · disponible en "+ZoneStatus.countdown((long)zone.respawnSeconds()*1000));}}catch(Exception error){try{ledger.put(new Run(run.uuid(),run.zone(),run.wave(),Phase.REVIEW,0,run.spawns(),run.players()));}catch(Exception suppressed){error.addSuppressed(suppressed);}ZianMobs.LOGGER.error("Encounter reward preserved for review",error);}}
 private void announce(ZoneSpec zone,String message){var text=Component.literal(zone.name()+" · "+message).withStyle(net.minecraft.ChatFormatting.GOLD);for(var player:server.getPlayerList().getPlayers())if(player.isAlive()&&!player.isSpectator()&&zone.contains(dimension(player),player.getX(),player.getY(),player.getZ())){player.sendSystemMessage(text);player.displayClientMessage(text,true);}}
 ItemStack item(String text){try{var parsed=ItemStack.parseOptional(server.registryAccess(),TagParser.parseTag(text));Tuning.update(parsed);return parsed;}catch(Exception error){throw new IllegalArgumentException("Objeto ilegible",error);}}
 private void grant(UUID player,String key,String preset,BlockPos pos,ServerLevel world)throws Exception{
  var old=rewards.latest(player,key);if(old==null){var loot=config.loot().get(preset);List<ItemStack> stacks=new ArrayList<>();var random=new java.security.SecureRandom();if(!loot.table().isEmpty()){var table=server.reloadableRegistries().getLootTable(ResourceKey.create(Registries.LOOT_TABLE,ResourceLocation.parse(loot.table())));var params=new LootParams.Builder(world).withParameter(LootContextParams.ORIGIN,Vec3.atCenterOf(pos)).create(LootContextParamSets.CHEST);stacks.addAll(table.getRandomItems(params));Collections.shuffle(stacks,random);if(stacks.size()>loot.rolls())stacks.subList(loot.rolls(),stacks.size()).clear();}else for(var entry:loot.independent()?WeightedLoot.independent(loot.entries(),random):WeightedLoot.select(loot.entries(),loot.rolls(),random)){var stack=item(entry.item());stack.setCount(entry.min()+random.nextInt(entry.max()-entry.min()+1));stacks.add(stack);}if(stacks.isEmpty()&&!loot.independent())throw new IllegalStateException("La tabla no produce objetos");var items=stacks.stream().map(s->s.save(server.registryAccess()).toString()).toList();rewards.reserveAt(player,key,new RewardDefinition("",0,items),System.currentTimeMillis(),UUID.nameUUIDFromBytes(key.getBytes(java.nio.charset.StandardCharsets.UTF_8)),loot.independent());old=rewards.latest(player,key);}var online=server.getPlayerList().getPlayer(player);if(online!=null)deliver(online,old.id());
 }
 private boolean fits(ServerPlayer player,ItemStack stack){int space=0;for(int i=0;i<36;i++){var slot=player.getInventory().getItem(i);space+=slot.isEmpty()?stack.getMaxStackSize():ItemStack.isSameItemSameComponents(slot,stack)?Math.max(0,slot.getMaxStackSize()-slot.getCount()):0;if(space>=stack.getCount())return true;}return false;}
 private void deliver(ServerPlayer player,UUID claim)throws Exception{reviewRetired(player.getUUID());RewardDelivery.deliver(rewards,player.getUUID(),claim,new RewardDelivery.Port(){public String unavailable(RewardClaim.Part part){if(!player.isAlive()||player.isRemoved())return "player_unavailable";var stack=item(part.data());return stack.isEmpty()?"invalid_item":fits(player,stack)?null:"inventory_full";}public RewardDelivery.Result apply(RewardClaim.Part part)throws Exception{var stack=item(part.data());player.getInventory().add(stack);if(!stack.isEmpty())return RewardDelivery.Result.UNCERTAIN;player.getInventory().setChanged();player.inventoryMenu.broadcastChanges();var expected=player.saveWithoutId(new CompoundTag()).get("Inventory");server.getPlayerList().save(player);Path saved=server.getWorldPath(LevelResource.PLAYER_DATA_DIR).resolve(player.getUUID()+".dat");try(var channel=FileChannel.open(saved,StandardOpenOption.WRITE)){channel.force(true);}return expected.equals(NbtIo.readCompressed(saved,NbtAccounter.create(8L*1024*1024)).get("Inventory"))?RewardDelivery.Result.APPLIED:RewardDelivery.Result.UNCERTAIN;}});var value=rewards.get(player.getUUID(),claim);player.sendSystemMessage(Component.literal(value.complete()?"Zian Mobs: recompensa entregada.":value.review()?"Entrega en revisión; no se repetirá automáticamente.":"Recompensa pendiente: libera espacio y usa /zianmobs pending."));}
 @FunctionalInterface private interface Action{void run()throws Exception;}
 private int action(CommandSourceStack source,Action action){try{ready();action.run();source.sendSuccess(()->Component.literal("Zian Mobs: operación completada."),false);return 1;}catch(Exception error){source.sendFailure(Component.literal(error.getMessage()==null?"Operación rechazada":error.getMessage()));return 0;}}
 private static String word(CommandContext<CommandSourceStack> c,String name){return StringArgumentType.getString(c,name);}
 private RequiredArgumentBuilder<CommandSourceStack,String> arg(String name,java.util.function.Supplier<Set<String>> values){return Commands.argument(name,StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(config==null?Set.of():values.get(),b));}
 private void commands(com.mojang.brigadier.CommandDispatcher<CommandSourceStack> dispatcher){
  var root=Commands.literal("zianmobs").requires(s->true).executes(c->{if(c.getSource().getEntity() instanceof ServerPlayer player&&com.ianblk.zianmobs.permission.MobsPermissions.allows(player,"admin"))admin.request(player,"home","");else c.getSource().sendSuccess(()->Component.literal("Zian Mobs · /zianmobs pending · Administración: mob, loot, zone, reload"),false);return 1;});
  root.then(Commands.literal("rewards").requires(s->com.ianblk.zianmobs.permission.MobsPermissions.allows(s,"loot")).executes(c->{PersonalRewards.open(c.getSource().getPlayerOrException());return 1;}));
  root.then(Commands.literal("pending").requires(s->com.ianblk.zianmobs.permission.MobsPermissions.allows(s,"loot")).executes(c->action(c.getSource(),()->{var player=c.getSource().getPlayerOrException();for(var claim:rewards.forPlayer(player.getUUID()))if(!claim.complete())deliver(player,claim.id());})));
  root.then(Commands.literal("reload").requires(s->com.ianblk.zianmobs.permission.MobsPermissions.allows(s,"admin")).executes(c->action(c.getSource(),()->{if(ledger.all().stream().anyMatch(r->r.phase()==Phase.ACTIVE||r.phase()==Phase.WAITING))throw new IllegalStateException("Cancela los encuentros activos antes de recargar");var next=AtomicJson.read(configFile,Config.class,config);validateRegistry(next);config=next;})));
  root.then(Commands.literal("mob").requires(s->com.ianblk.zianmobs.permission.MobsPermissions.allows(s,"admin"))
   .then(Commands.literal("list").executes(c->action(c.getSource(),()->c.getSource().sendSuccess(()->Component.literal(String.join(", ",config.mobs().keySet())),false))))
   .then(Commands.literal("loot").then(arg("mob",()->config.mobs().keySet()).then(arg("loot",()->config.loot().keySet()).executes(c->action(c.getSource(),()->{var id=word(c,"mob");var s=Objects.requireNonNull(config.mobs().get(id),"Mob inexistente");var next=new LinkedHashMap<>(config.mobs());next.put(id,new MobSpec(s.id(),s.name(),s.entity(),s.health(),s.damage(),s.armor(),s.toughness(),s.knockback(),s.effects(),s.equipment(),word(c,"loot"),s.boss()));save(new Config(7,next,config.loot(),config.zones()));}))))));
  root.then(Commands.literal("loot").requires(s->com.ianblk.zianmobs.permission.MobsPermissions.allows(s,"admin")).then(Commands.literal("create").then(Commands.argument("id",StringArgumentType.word()).executes(c->action(c.getSource(),()->{String id=word(c,"id");if(config.loot().containsKey(id))throw new IllegalArgumentException("Loot ya existente; usa add");var item=c.getSource().getPlayerOrException().getMainHandItem();if(item.isEmpty())throw new IllegalArgumentException("Sostén el objeto que quieres entregar");var next=new LinkedHashMap<>(config.loot());next.put(id,new LootSpec(id,"MOB",1,List.of(new LootEntry(item.copyWithCount(1).save(server.registryAccess()).toString(),100,item.getCount(),item.getCount())),""));save(new Config(7,config.mobs(),next,config.zones()));}))))
   .then(Commands.literal("add").then(arg("id",()->config.loot().keySet()).then(Commands.argument("weight",IntegerArgumentType.integer(1,10000)).executes(c->action(c.getSource(),()->{String id=word(c,"id");var previous=Objects.requireNonNull(config.loot().get(id),"Loot inexistente");var item=c.getSource().getPlayerOrException().getMainHandItem();if(item.isEmpty())throw new IllegalArgumentException("Sostén un objeto");var entries=new ArrayList<>(previous.entries());entries.add(new LootEntry(item.copyWithCount(1).save(server.registryAccess()).toString(),IntegerArgumentType.getInteger(c,"weight"),item.getCount(),item.getCount()));var next=new LinkedHashMap<>(config.loot());next.put(id,new LootSpec(id,previous.category(),previous.rolls(),entries,previous.table(),previous.independent()));save(new Config(7,config.mobs(),next,config.zones()));}))))));
  var zones=Commands.literal("zone").requires(s->com.ianblk.zianmobs.permission.MobsPermissions.allows(s,"admin"));
  zones.then(Commands.literal("create").then(Commands.argument("id",StringArgumentType.word()).then(arg("mob",()->config.mobs().keySet()).then(Commands.argument("radius",IntegerArgumentType.integer(2,64)).executes(c->action(c.getSource(),()->{String id=word(c,"id");if(config.zones().containsKey(id))throw new IllegalArgumentException("Zona ya existente");var p=c.getSource().getPlayerOrException();var center=point(p);int radius=IntegerArgumentType.getInteger(c,"radius");var bounds=CenteredZone.bounds(center,radius,radius,4,2);var next=new LinkedHashMap<>(config.zones());next.put(id,new ZoneSpec(id,dimension(p),bounds.first(),bounds.second(),List.of(),List.of(word(c,"mob")),1,5,60,"",false,center,radius,radius,4,2,id));save(new Config(7,config.mobs(),config.loot(),next));}))))));
  zones.then(Commands.literal("point").then(arg("id",()->config.zones().keySet()).executes(c->action(c.getSource(),()->{var z=zone(word(c,"id"));requireIdle(z);var p=c.getSource().getPlayerOrException();if(!z.contains(dimension(p),p.getX(),p.getY(),p.getZ()))throw new IllegalArgumentException("El punto debe estar dentro de su zona");var points=new ArrayList<>(z.points());points.add(point(p));putZone(copy(z,points,z.enabled(),z.waves(),z.pauseSeconds(),z.respawnSeconds(),z.completionLoot()));}))));
  for(boolean enabled:List.of(true,false))zones.then(Commands.literal(enabled?"enable":"disable").then(arg("id",()->config.zones().keySet()).executes(c->action(c.getSource(),()->{var z=zone(word(c,"id"));requireIdle(z);putZone(copy(z,z.points(),enabled,z.waves(),z.pauseSeconds(),z.respawnSeconds(),z.completionLoot()));}))));
  zones.then(Commands.literal("loot").then(arg("id",()->config.zones().keySet()).then(arg("loot",()->config.loot().keySet()).executes(c->action(c.getSource(),()->{var z=zone(word(c,"id"));requireIdle(z);putZone(copy(z,z.points(),z.enabled(),z.waves(),z.pauseSeconds(),z.respawnSeconds(),word(c,"loot")));})))));
  zones.then(Commands.literal("times").then(arg("id",()->config.zones().keySet()).then(Commands.argument("waves",IntegerArgumentType.integer(1,16)).then(Commands.argument("pause",IntegerArgumentType.integer(1,3600)).then(Commands.argument("respawn",IntegerArgumentType.integer(10,2592000)).executes(c->action(c.getSource(),()->{var z=zone(word(c,"id"));requireIdle(z);putZone(copy(z,z.points(),z.enabled(),IntegerArgumentType.getInteger(c,"waves"),IntegerArgumentType.getInteger(c,"pause"),IntegerArgumentType.getInteger(c,"respawn"),z.completionLoot()));})))))));
  zones.then(Commands.literal("boss").then(arg("id",()->config.zones().keySet()).then(arg("boss",()->{var ids=new LinkedHashSet<String>();ids.add("none");config.mobs().values().stream().filter(MobSpec::boss).map(MobSpec::id).forEach(ids::add);return ids;}).executes(c->action(c.getSource(),()->{var zone=zone(word(c,"id"));requireIdle(zone);putZone(zone.plan(word(c,"boss").equals("none")?"":word(c,"boss"),zone.waveTeams()));})))));
  zones.then(Commands.literal("wave").then(arg("id",()->config.zones().keySet()).then(Commands.argument("wave",IntegerArgumentType.integer(1,16)).then(Commands.argument("mobs",StringArgumentType.greedyString()).suggests((c,b)->suggestTeam(b)).executes(c->action(c.getSource(),()->{var zone=zone(word(c,"id"));requireIdle(zone);int n=IntegerArgumentType.getInteger(c,"wave");var teams=new ArrayList<List<String>>(zone.waveTeams());while(teams.size()<n)teams.add(List.of());teams.set(n-1,word(c,"mobs").equals("default")?List.of():Arrays.stream(word(c,"mobs").split("[, ]+")).filter(v->!v.isBlank()).toList());putZone(zone.plan(zone.boss(),teams));}))))));
  zones.then(Commands.literal("status").then(arg("id",()->config.zones().keySet()).executes(c->action(c.getSource(),()->{var z=zone(word(c,"id"));var run=ledger.get(z.id());c.getSource().sendSuccess(()->Component.literal(z.id()+" · "+(z.enabled()?"activada":"desactivada")+" · "+(run==null?"sin encuentro":run.phase()+" · espera "+Math.max(0,(run.readyAt()-System.currentTimeMillis()+999)/1000)+" s")),false);})))) ;
  zones.then(Commands.literal("cancel").then(arg("id",()->config.zones().keySet()).executes(c->action(c.getSource(),()->{var z=zone(word(c,"id"));var run=ledger.get(z.id());if(run==null)return;ledger.put(new Run(run.uuid(),run.zone(),run.wave(),Phase.CANCELLED,0,run.spawns(),run.players()));for(var slot:run.spawns()){var entity=level(z.dimension()).getEntity(slot.uuid());if(entity!=null&&entity.getPersistentData().getString("ZianMobsRun").equals(run.uuid().toString()))entity.discard();}putZone(copy(z,z.points(),false,z.waves(),z.pauseSeconds(),z.respawnSeconds(),z.completionLoot()));}))));

  var mobAdmin=Commands.literal("mob").requires(source->com.ianblk.zianmobs.permission.MobsPermissions.allows(source,"admin"));
  mobAdmin.then(Commands.literal("create")
   .then(Commands.argument("id",StringArgumentType.word())
    .then(Commands.argument("entity",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(BuiltInRegistries.ENTITY_TYPE.keySet().stream().map(Object::toString),b))
     .executes(c->action(c.getSource(),()->{String id=word(c,"id");if(config.mobs().containsKey(id))throw new IllegalArgumentException("Mob ya existente");var next=new LinkedHashMap<>(config.mobs());next.put(id,new MobSpec(id,id,word(c,"entity"),25,3,0,0,0,List.of(),Map.of(),"",false));save(new Config(7,next,config.loot(),config.zones()));})))));
  mobAdmin.then(Commands.literal("attributes")
   .then(arg("id",()->config.mobs().keySet())
    .then(Commands.argument("health",DoubleArgumentType.doubleArg(1,1024))
     .then(Commands.argument("damage",DoubleArgumentType.doubleArg(0,128))
      .then(Commands.argument("armor",DoubleArgumentType.doubleArg(0,30))
       .executes(c->action(c.getSource(),()->{var id=word(c,"id");var old=Objects.requireNonNull(config.mobs().get(id),"Mob inexistente");var next=new LinkedHashMap<>(config.mobs());next.put(id,new MobSpec(old.id(),old.name(),old.entity(),DoubleArgumentType.getDouble(c,"health"),DoubleArgumentType.getDouble(c,"damage"),DoubleArgumentType.getDouble(c,"armor"),old.toughness(),old.knockback(),old.effects(),old.equipment(),old.loot(),old.boss()));save(new Config(7,next,config.loot(),config.zones()));})))))));
  zones.then(Commands.literal("team").then(arg("id",()->config.zones().keySet())
   .then(Commands.argument("mobs",StringArgumentType.greedyString()).suggests((c,b)->suggestTeam(b))
    .executes(c->action(c.getSource(),()->{var z=zone(word(c,"id"));requireIdle(z);if(z.stages()!=null)throw new IllegalArgumentException("Edita las criaturas de cada etapa desde Zonas → Encuentro");var team=Arrays.stream(word(c,"mobs").split("[, ]+")).filter(v->!v.isBlank()).toList();putZone(new ZoneSpec(z.id(),z.dimension(),z.first(),z.second(),z.points(),team,z.waves(),z.pauseSeconds(),z.respawnSeconds(),z.completionLoot(),z.enabled(),z.center(),z.radiusX(),z.radiusZ(),z.above(),z.below(),z.name(),z.boss(),z.waveTeams(),z.stages(),z.autoSpawn()));})))));
  var review=Commands.literal("review").requires(source->com.ianblk.zianmobs.permission.MobsPermissions.allows(source,"admin"));
  review.then(arg("player",()->new LinkedHashSet<>(Arrays.asList(server.getPlayerNames()))).executes(c->action(c.getSource(),()->{var owner=CompanionAccessCommands.target(c.getSource(),word(c,"player"));for(var claim:rewards.forPlayer(owner))if(!claim.complete())c.getSource().sendSuccess(()->Component.literal(reference(owner,claim.id())+" · "+server.getProfileCache().get(owner).map(com.mojang.authlib.GameProfile::getName).orElse("Jugador sin conexión")+" · "+claim.trainer()+" · "+claim.parts()),false);})));
  var resolve=Commands.literal("resolve").requires(source->com.ianblk.zianmobs.permission.MobsPermissions.allows(source,"admin"));
  resolve.then(arg("player",()->new LinkedHashSet<>(Arrays.asList(server.getPlayerNames())))
   .then(Commands.argument("claim",StringArgumentType.word()).suggests((c,b)->{try{var owner=CompanionAccessCommands.target(c.getSource(),word(c,"player"));return SharedSuggestionProvider.suggest(rewards.forPlayer(owner).stream().filter(claim->!claim.complete()).map(claim->reference(owner,claim.id())),b);}catch(RuntimeException error){return b.buildFuture();}})
    .then(Commands.argument("part",IntegerArgumentType.integer(1,32))
     .then(Commands.argument("evidence",StringArgumentType.greedyString())
      .executes(c->action(c.getSource(),()->{var owner=CompanionAccessCommands.target(c.getSource(),word(c,"player"));var claim=resolveReference(CompanionAccessCommands.target(c.getSource(),word(c,"player")),word(c,"claim"));var actor=c.getSource().getEntity()==null?new UUID(0,0):c.getSource().getEntity().getUUID();rewards.resolve(owner,claim,IntegerArgumentType.getInteger(c,"part")-1,actor,"confirmed_compensated",word(c,"evidence"));ZianMobs.LOGGER.info("Reward review acknowledged owner={} claim={} admin={}",owner,claim,actor);c.getSource().sendSuccess(()->Component.literal("Entrega marcada como revisada. Este comando no añade objetos; confirma antes la compensación."),true);}))))));
  root.then(review);root.then(resolve);root.then(mobAdmin);root.then(zones);dispatcher.register(root);
 }
 void claimPersonal(ServerPlayer p,UUID id)throws Exception{ready();var claim=rewards.get(p.getUUID(),id);if(claim==null||claim.complete()||claim.review())throw new IllegalArgumentException("Premio no disponible para reclamar");deliver(p,id);}
 void reviewRetired(UUID owner)throws Exception{for(var claim:rewards.forPlayer(owner))for(int i=0;i<claim.parts().size();i++){var part=claim.parts().get(i);if(part.kind()==RewardClaim.Kind.ITEM&&part.phase()==RewardClaim.Phase.PENDING&&ContentRetirement.itemTag(part.data())){rewards.phase(claim.id(),i,RewardClaim.Phase.APPLYING,"Retirada de contenido: bloquear entrega para revisión; no se entregan objetos");rewards.phase(claim.id(),i,RewardClaim.Phase.REVIEW_REQUIRED,"Objeto retirado en beta.4; requiere comprobación o compensación manual");}}}
 void smokeWave(UUID player)throws Exception{if(!Boolean.getBoolean("zianmobs.smoke"))throw new IllegalStateException("Test disabled");var old=ledger.get("smoke_zone");begin(zone("smoke_zone"),Set.of(player),old==null?1:old.wave()+1,old==null?UUID.randomUUID():old.uuid());}
 void smokeDeliver(ServerPlayer player)throws Exception{if(!Boolean.getBoolean("zianmobs.smoke"))throw new IllegalStateException("Test disabled");for(var claim:rewards.forPlayer(player.getUUID()))if(!claim.complete())deliver(player,claim.id());}
 void cancel(ZoneSpec zone)throws Exception{var run=ledger.get(zone.id());if(run!=null){ledger.put(new Run(run.uuid(),run.zone(),run.wave(),Phase.CANCELLED,0,run.spawns(),run.players()));for(var slot:run.spawns()){var entity=level(zone.dimension()).getEntity(slot.uuid());if(entity!=null&&entity.getPersistentData().getString("ZianMobsRun").equals(run.uuid().toString()))entity.discard();}}putZone(copy(zone,zone.points(),false,zone.waves(),zone.pauseSeconds(),zone.respawnSeconds(),zone.completionLoot()));}
 private HumanReferences references;
 String reference(UUID owner,UUID id){try{if(references==null)references=new HumanReferences(root.resolve("references.json"),"MOBS");return references.reference(id,owner,server.getProfileCache().get(owner).map(com.mojang.authlib.GameProfile::getName).orElse("JUGADOR"));}catch(java.io.IOException error){throw new IllegalStateException(error);}}
 UUID resolveReference(UUID owner,String value){try{if(references==null)references=new HumanReferences(root.resolve("references.json"),"MOBS");return references.resolve(value,owner);}catch(java.io.IOException error){throw new IllegalStateException(error);}}
 private static Point point(ServerPlayer p){return new Point(p.getX(),p.getY(),p.getZ(),p.getYRot());}
 ZoneSpec zone(String id){return Objects.requireNonNull(config.zones().get(id),"Zona inexistente");}
 void requireIdle(ZoneSpec zone){var run=ledger.get(zone.id());if(run!=null&&(run.phase()==Phase.ACTIVE||run.phase()==Phase.WAITING||run.phase()==Phase.REVIEW))throw new IllegalStateException("Cancela el encuentro antes de cambiar la zona");}
 void putZone(ZoneSpec z)throws Exception{var old=config.zones().get(z.id());var next=new LinkedHashMap<>(config.zones());next.put(z.id(),z);save(new Config(7,config.mobs(),config.loot(),next));if(old!=null)ledger.updateWait(z.id(),old.pauseSeconds(),z.pauseSeconds(),old.respawnSeconds(),z.respawnSeconds());}
 private java.util.concurrent.CompletableFuture<com.mojang.brigadier.suggestion.Suggestions> suggestTeam(com.mojang.brigadier.suggestion.SuggestionsBuilder builder){
  String value=builder.getRemaining();int split=Math.max(value.lastIndexOf(','),value.lastIndexOf(' '));
  var next=builder.createOffset(builder.getStart()+split+1);
  net.minecraft.commands.SharedSuggestionProvider.suggest(config==null?List.of():config.mobs().keySet(),next);
  if(split<0)net.minecraft.commands.SharedSuggestionProvider.suggest(List.of("default"),next);
  return next.buildFuture();
 }
 private static ZoneSpec copy(ZoneSpec z,List<Point> points,boolean enabled,int waves,int pause,int respawn,String loot){if(z.stages()!=null&&waves!=z.waves())throw new IllegalArgumentException("Cambia las etapas desde Zonas → Encuentro");return new ZoneSpec(z.id(),z.dimension(),z.first(),z.second(),points,z.team(),waves,pause,respawn,loot,enabled,z.center(),z.radiusX(),z.radiusZ(),z.above(),z.below(),z.name(),z.boss(),z.waveTeams(),z.stages(),z.autoSpawn());}
}
